-- STEP 3: Tabella servizi multipli per targa
-- ============================================================
CREATE TABLE IF NOT EXISTS veicoli_servizi (
  id bigserial PRIMARY KEY,
  targa text NOT NULL,
  numero_servizio integer,
  servizio text,
  tipo_servizio text,
  canone numeric,
  prezzo_riservato numeric,
  data_rinnovo date,
  data_termine date
);
TRUNCATE TABLE veicoli_servizi;

